// x86 operand types
typedef enum x86_op_type {
  X86_OP_INVALID = 0,  // Uninitialized
  X86_OP_REG,          // Register operand
  X86_OP_IMM,          // Immediate operand
  X86_OP_MEM = 3,      // Memory operand
  X86_OP_FP,           // Floating-point immediate operand (unused in stub)
} x86_op_type;

// Memory operand for x86
typedef struct x86_op_mem {
  unsigned int  base;   // Base register (x86_reg)
  unsigned int  index;  // Index register (x86_reg)
  int           scale;  // Scale factor (1, 2, 4, or 8)
  int64_t       disp;   // Displacement value
} x86_op_mem;

